"use client";

import { useEffect, useMemo, useState } from "react";
import {
  ArcElement,
  BarElement,
  CategoryScale,
  Chart as ChartJS,
  Filler,
  Legend,
  LineElement,
  LinearScale,
  PointElement,
  Tooltip
} from "chart.js";
import { Bar, Doughnut, Line } from "react-chartjs-2";
import { activeStudent, academicSubjects, students as initialStudents, subjectAttendance, timetable, type Student } from "@/lib/erp-data";

ChartJS.register(ArcElement, BarElement, CategoryScale, Filler, Legend, LineElement, LinearScale, PointElement, Tooltip);

type Role = "student" | "faculty" | "admin";
type StudentPage = "Dashboard" | "My Profile" | "Attendance" | "Academics" | "Timetable" | "Notifications" | "Reports" | "Settings";
type StaffPage = "Dashboard" | "Students" | "Attendance" | "Reports" | "Departments" | "Courses" | "Users" | "Settings";
type Page = StudentPage | StaffPage;

const navigation: Record<Role, { label: Page; icon: string }[]> = {
  student: [
    { label: "Dashboard", icon: "fa-grid-2" }, { label: "My Profile", icon: "fa-user" }, { label: "Attendance", icon: "fa-calendar-check" },
    { label: "Academics", icon: "fa-graduation-cap" }, { label: "Timetable", icon: "fa-table-cells-large" }, { label: "Notifications", icon: "fa-bell" },
    { label: "Reports", icon: "fa-chart-line" }, { label: "Settings", icon: "fa-gear" }
  ],
  faculty: [
    { label: "Dashboard", icon: "fa-grid-2" }, { label: "Students", icon: "fa-users" }, { label: "Attendance", icon: "fa-calendar-check" },
    { label: "Reports", icon: "fa-chart-pie" }, { label: "Settings", icon: "fa-gear" }
  ],
  admin: [
    { label: "Dashboard", icon: "fa-grid-2" }, { label: "Students", icon: "fa-user-graduate" }, { label: "Attendance", icon: "fa-calendar-check" },
    { label: "Departments", icon: "fa-building-columns" }, { label: "Courses", icon: "fa-book-open" }, { label: "Users", icon: "fa-users-gear" },
    { label: "Reports", icon: "fa-chart-pie" }, { label: "Settings", icon: "fa-gear" }
  ]
};

const progressClass = (value: number) => value >= 75 ? "success" : value >= 60 ? "warning" : "danger";
const initials = (name: string) => name.split(" ").map((piece) => piece[0]).slice(0, 2).join("");

function PercentageBadge({ value }: { value: number }) {
  const cls = progressClass(value);
  return <span className={`status-pill ${cls}`}>{value.toFixed(1)}%</span>;
}

function DonutChart({ value = 82.4 }: { value?: number }) {
  return <Doughnut
    data={{ labels: ["Present", "Absent"], datasets: [{ data: [value, 100 - value], backgroundColor: ["#2563eb", "#e8eef8"], hoverBackgroundColor: ["#1d4ed8", "#d7e2f2"], borderWidth: 0 }] }}
    options={{ responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false }, tooltip: { callbacks: { label: (item) => `${item.label}: ${item.raw}%` } } } }}
  />;
}

function TrendChart() {
  return <Line
    data={{ labels: ["Aug", "Sep", "Oct", "Nov", "Dec", "Jan"], datasets: [{ label: "Attendance", data: [76, 81, 78, 85, 82, 88], borderColor: "#2563eb", backgroundColor: "rgba(37,99,235,.10)", fill: true, tension: .42, borderWidth: 3, pointBackgroundColor: "#fff", pointBorderColor: "#2563eb", pointBorderWidth: 3, pointRadius: 4 }] }}
    options={{ responsive: true, maintainAspectRatio: false, scales: { y: { min: 50, max: 100, grid: { color: "rgba(148,163,184,.15)" }, ticks: { callback: (value) => `${value}%` } }, x: { grid: { display: false } } }, plugins: { legend: { display: false } } }}
  />;
}

function MonthlyChart() {
  return <Bar
    data={{ labels: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"], datasets: [{ label: "Class attendance", data: [86, 76, 92, 84, 89, 72], borderRadius: 8, backgroundColor: ["#2563eb", "#60a5fa", "#2563eb", "#60a5fa", "#2563eb", "#93c5fd"], borderSkipped: false }] }}
    options={{ responsive: true, maintainAspectRatio: false, scales: { y: { min: 0, max: 100, grid: { color: "rgba(148,163,184,.15)" }, ticks: { callback: (value) => `${value}%` } }, x: { grid: { display: false } } }, plugins: { legend: { display: false } } }}
  />;
}

function DepartmentChart() {
  return <Bar
    data={{ labels: ["CSE", "IT", "ECE", "ME", "MBA"], datasets: [{ label: "Avg. Attendance", data: [82, 78, 74, 71, 85], backgroundColor: ["#2563eb", "#4f8df7", "#7eaff9", "#a5c8fc", "#d4e5ff"], borderRadius: 8, borderSkipped: false }] }}
    options={{ responsive: true, maintainAspectRatio: false, indexAxis: "y", scales: { x: { min: 0, max: 100, grid: { color: "rgba(148,163,184,.15)" }, ticks: { callback: (value) => `${value}%` } }, y: { grid: { display: false } } }, plugins: { legend: { display: false } } }}
  />;
}

function AppLogo({ light = false }: { light?: boolean }) {
  return <div className="brand"><div className={`brand-mark ${light ? "light" : ""}`}><i className="fa-solid fa-a"></i></div><div><strong>Aurora</strong><span>UNIVERSITY</span></div></div>;
}

function StatCard({ icon, label, value, note, tone = "blue" }: { icon: string; label: string; value: string; note: string; tone?: string }) {
  return <article className="stat-card"><div className={`stat-icon ${tone}`}><i className={`fa-solid ${icon}`}></i></div><div className="stat-content"><span>{label}</span><strong>{value}</strong><small className={note.includes("↓") || note.includes("below") ? "negative" : "positive"}>{note}</small></div></article>;
}

function LoginScreen({ onLogin }: { onLogin: (role: Role) => void }) {
  const [username, setUsername] = useState("12345678");
  const [password, setPassword] = useState("student123");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const demo = [
    { role: "student" as const, icon: "fa-user-graduate", label: "Student", username: "12345678", password: "student123" },
    { role: "faculty" as const, icon: "fa-chalkboard-user", label: "Faculty", username: "faculty01", password: "faculty123" },
    { role: "admin" as const, icon: "fa-shield-halved", label: "Administrator", username: "admin", password: "admin123" }
  ];
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setMessage(""); setLoading(true);
    try {
      const response = await fetch("/api/auth/login", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, password }) });
      const result = await response.json() as { message?: string; user?: { role: Role } };
      if (!response.ok || !result.user) { setMessage(result.message || "Unable to sign in."); return; }
      localStorage.setItem("aurora-role", result.user.role); onLogin(result.user.role);
    } catch { setMessage("Connection issue. Please try again."); } finally { setLoading(false); }
  };
  return <main className="login-page">
    <div className="login-orb orb-one"></div><div className="login-orb orb-two"></div><div className="login-grid"></div>
    <section className="login-shell">
      <aside className="login-welcome"><AppLogo light /><div className="welcome-copy"><p className="eyebrow light-eyebrow">STUDENT SUCCESS PLATFORM</p><h1>More than attendance.<br /><em>Your academic journey.</em></h1><p>One trusted place for your classes, performance and university life.</p></div><div className="login-feature"><i className="fa-solid fa-sparkles"></i><span>Designed for the Aurora community</span></div><div className="welcome-footer"><span>© 2025 Aurora University</span><span>Secure campus access</span></div></aside>
      <section className="login-form-panel"><div className="login-mobile-logo"><AppLogo /></div><div className="login-heading"><span className="tiny-label">WELCOME BACK</span><h2>Sign in to your portal</h2><p>Use your university credentials to continue.</p></div>
        <form onSubmit={submit}><label>University ID <div className="input-wrap"><i className="fa-regular fa-user"></i><input value={username} onChange={(e) => setUsername(e.target.value)} placeholder="Enter registration number" autoComplete="username" /></div></label><label>Password <div className="input-wrap"><i className="fa-solid fa-lock"></i><input value={password} onChange={(e) => setPassword(e.target.value)} type="password" placeholder="Enter password" autoComplete="current-password" /></div></label><div className="form-row"><label className="check-label"><input type="checkbox" defaultChecked /> <span>Remember me</span></label><button type="button" className="text-button">Forgot password?</button></div>{message && <p className="form-message"><i className="fa-solid fa-circle-exclamation"></i>{message}</p>}<button className="primary-button login-button" disabled={loading}>{loading ? <><i className="fa-solid fa-circle-notch fa-spin"></i> Verifying access...</> : <>Sign in securely <i className="fa-solid fa-arrow-right"></i></>}</button></form>
        <div className="demo-area"><div className="demo-divider"><span>DEMO ACCESS</span></div><div className="demo-cards">{demo.map((account) => <button key={account.role} type="button" onClick={() => { setUsername(account.username); setPassword(account.password); }} className="demo-card"><i className={`fa-solid ${account.icon}`}></i><span>{account.label}</span></button>)}</div><p>Choose a profile to load its demo credentials</p></div>
      </section>
    </section>
  </main>;
}

function Topbar({ role, page, darkMode, onDarkMode, onLogout, onMobileMenu, query, setQuery }: { role: Role; page: Page; darkMode: boolean; onDarkMode: () => void; onLogout: () => void; onMobileMenu: () => void; query: string; setQuery: (value: string) => void }) {
  const person = role === "student" ? activeStudent : role === "faculty" ? { name: "Dr. Neha Verma", image: "https://i.pravatar.cc/160?img=49" } : { name: "Admin Office", image: "https://i.pravatar.cc/160?img=68" };
  return <header className="topbar"><div className="topbar-title"><button className="mobile-menu" onClick={onMobileMenu}><i className="fa-solid fa-bars"></i></button><div><span className="breadcrumb">{role === "student" ? "Student Portal" : role === "faculty" ? "Faculty Workspace" : "Administration"}</span><h1>{page}</h1></div></div><div className="topbar-actions"><div className="global-search"><i className="fa-solid fa-magnifying-glass"></i><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={role === "student" ? "Search your portal..." : "Search students, registration..."} /></div><button className="icon-button theme-toggle" onClick={onDarkMode} title="Toggle color mode"><i className={`fa-solid ${darkMode ? "fa-sun" : "fa-moon"}`}></i></button><button className="icon-button notification-button"><i className="fa-regular fa-bell"></i><b>3</b></button><div className="profile-menu"><img src={person.image} alt="Profile" /><div className="profile-name"><strong>{person.name}</strong><span>{role === "student" ? "24CSE1001 · CSE" : role === "faculty" ? "Faculty · CSE" : "System administrator"}</span></div><button onClick={onLogout} className="logout-mini" title="Sign out"><i className="fa-solid fa-arrow-right-from-bracket"></i></button></div></div></header>;
}

function Sidebar({ role, page, setPage, open, close }: { role: Role; page: Page; setPage: (page: Page) => void; open: boolean; close: () => void }) {
  return <aside className={`sidebar ${open ? "sidebar-open" : ""}`}><div className="sidebar-head"><AppLogo /><button className="sidebar-close" onClick={close}><i className="fa-solid fa-xmark"></i></button></div><div className="role-identity"><div className="identity-icon"><i className={`fa-solid ${role === "student" ? "fa-user-graduate" : role === "faculty" ? "fa-chalkboard-user" : "fa-shield-halved"}`}></i></div><div><strong>{role === "student" ? "Student Workspace" : role === "faculty" ? "Faculty Workspace" : "Admin Console"}</strong><span>Academic Year 2024–25</span></div></div><nav>{navigation[role].map((item) => <button key={item.label} onClick={() => { setPage(item.label); close(); }} className={`nav-link ${page === item.label ? "active" : ""}`}><i className={`fa-solid ${item.icon}`}></i><span>{item.label}</span>{item.label === "Notifications" && role === "student" ? <b>3</b> : null}</button>)}</nav><div className="sidebar-bottom"><div className="help-card"><i className="fa-regular fa-circle-question"></i><div><strong>Need help?</strong><span>Contact support</span></div></div><p><i className="fa-solid fa-circle"></i> Systems operational</p></div></aside>;
}

